mapper.select:
SELECT id, dialect, putonghua, word, pinyin
FROM study_word_card
WHERE dialect = #{dialect}
ORDER BY RAND()
LIMIT #{limit}

SELECT id, dialect, putonghua, word, pinyin
FROM study_word_card
WHERE id = #{id} AND dialect = #{dialect}

mapper.update:
UPDATE study_word_card
SET putonghua = #{putonghua}, word = #{word}, pinyin = #{pinyin}
WHERE id = #{id} AND dialect = #{dialect}
